// A failed branch experiment must not describe main as broken. Ignore builds
// still running, so they cannot conceal the last completed failure.
const response = await this.helpers.httpRequest({method: 'GET',
  url: 'http://127.0.0.1:8409/api/v1/repos/hugo-berendi/yomi/actions/tasks',
  qs: {limit: 100}, json: true, timeout: 20000});
if (!Array.isArray(response.workflow_runs)) throw new Error('Forgejo returned no workflow runs');
const latest = new Map();
for (const run of [...response.workflow_runs].sort((a,b) => b.id - a.id)) {
  if (run.head_branch !== 'main' || !['success','failure','error','cancelled'].includes(run.status)) continue;
  const workflow = run.workflow_id ?? run.name;
  if (!latest.has(workflow)) latest.set(workflow, run);
}
return [...latest].map(([workflow, run]) => ({json: {
  source: 'forgejo-ci', severity: 'warning',
  title: `${workflow} on main ${run.status === 'success' ? 'recovered' : 'failed'}`,
  message: run.status === 'success' ? 'The latest completed main build passed.' : 'The latest completed main build failed. Open Forgejo Actions and inspect its failed job.',
  fingerprint: `forgejo-ci:main:${workflow}`, resolved: run.status === 'success',
  url: 'https://git.hugo-berendi.de/hugo-berendi/yomi/actions',
}}));
